{"cmd":"cat <<'NODE' > /root/update.js
const x = require('xlsx');

function cleanStr(v) {
  if (typeof v === 'string') return v.replace(/\u0000/g, '').trim();
  return v;
}

function setValue(ws, addr, v) {
  if (v === null || v === undefined || v === '') {
    delete ws[addr];
    return;
  }
  ws[addr] = { t: 'n', v };
}

function setFormula(ws, addr, f) {
  if (!f) {
    delete ws[addr];
    return;
  }
  ws[addr] = { t: 'n', f };
}

// Load PWT data
const pwtWb = x.readFile('pwt1001.xlsx');
const pwtWs = pwtWb.Sheets['Data'];
const pwtRange = x.utils.decode_range(pwtWs['!ref']);
const pwtHeaders = [];
for (let c = 0; c <= pwtRange.e.c; c++) {
  pwtHeaders.push(cleanStr(pwtWs[x.utils.encode_cell({ r: 0, c })]?.v));
}
const pwtIdxCountry = pwtHeaders.indexOf('countrycode');
const pwtIdxYear = pwtHeaders.indexOf('year');
const pwtIdxRnna = pwtHeaders.indexOf('rnna');
const pwtIdxRkna = pwtHeaders.indexOf('rkna');
const pwtData = new Map();
for (let r = 1; r <= pwtRange.e.r; r++) {
  const cc = cleanStr(pwtWs[x.utils.encode_cell({ r, c: pwtIdxCountry })]?.v);
  if (cc !== 'GEO') continue;
  const year = pwtWs[x.utils.encode_cell({ r, c: pwtIdxYear })]?.v;
  if (year < 1990 || year > 2023) continue;
  const rnna = pwtWs[x.utils.encode_cell({ r, c: pwtIdxRnna })]?.v;
  const rkna = pwtWs[x.utils.encode_cell({ r, c: pwtIdxRkna })]?.v;
  pwtData.set(year, { rnna, rkna });
}

// Load WEO data
const weoWb = x.readFile('weoapr2025all.xls');
const weoWs = weoWb.Sheets['Sheet1'];
const weoRange = x.utils.decode_range(weoWs['!ref']);
const weoHeaders = [];
for (let c = 0; c <= weoRange.e.c; c++) {
  weoHeaders.push(cleanStr(weoWs[x.utils.encode_cell({ r: 0, c })]?.v));
}
const weoIdxCountry = weoHeaders.indexOf('WEO Country Code');
const weoIdxSubject = weoHeaders.indexOf('WEO Subject Code');
const weoColByYear = {};
weoHeaders.forEach((h, i) => {
  const s = String(h);
  if (/^[0-9]{4}$/.test(s)) weoColByYear[parseInt(s, 10)] = i;
});
let rowNgdp = null;
let rowNgdpGr = null;
for (let r = 1; r <= weoRange.e.r; r++) {
  let cc = cleanStr(weoWs[x.utils.encode_cell({ r, c: weoIdxCountry })]?.v);
  let subj = cleanStr(weoWs[x.utils.encode_cell({ r, c: weoIdxSubject })]?.v);
  if (cc === '915' && subj === 'NGDP_R') rowNgdp = r;
  if (cc === '915' && subj === 'NGDP_RPCH') rowNgdpGr = r;
  if (rowNgdp && rowNgdpGr) break;
}
const weoData = new Map();
for (let y = 2000; y <= 2027; y++) {
  const c = weoColByYear[y];
  let v = weoWs[x.utils.encode_cell({ r: rowNgdp, c })]?.v;
  let g = weoWs[x.utils.encode_cell({ r: rowNgdpGr, c })]?.v;
  v = cleanStr(v);
  g = cleanStr(g);
  weoData.set(y, { gdp: v !== undefined && v !== '' ? parseFloat(v) : null, gr: g !== undefined && g !== '' ? parseFloat(g) : null });
}

// Load ECB CFC data
const cfcWb = x.readFile('cfc.csv');
const cfcWs = cfcWb.Sheets[cfcWb.SheetNames[0]];
const cfcRange = x.utils.decode_range(cfcWs['!ref']);
const cfcHeaders = [];
for (let c = 0; c <= cfcRange.e.c; c++) {
  cfcHeaders.push(cfcWs[x.utils.encode_cell({ r: 0, c })]?.v);
}
const cfcIdxTime = cfcHeaders.indexOf('TIME_PERIOD');
const cfcIdxValue = cfcHeaders.indexOf('OBS_VALUE');
const cfcData = new Map();
for (let r = 1; r <= cfcRange.e.r; r++) {
  const year = cfcWs[x.utils.encode_cell({ r, c: cfcIdxTime })]?.v;
  const val = cfcWs[x.utils.encode_cell({ r, c: cfcIdxValue })]?.v;
  if (year) cfcData.set(parseInt(year, 10), val);
}

// Load target workbook
const wb = x.readFile('test-supply.xlsx', { cellFormula: true });

// Update PWT sheet
const pwtSheet = wb.Sheets['PWT'];
// Header for rkna
pwtSheet['C1'] = { t: 's', v: 'rkna' };
for (let r = 2; r <= 35; r++) {
  const year = pwtSheet[`A${r}`]?.v;
  if (!year) continue;
  const entry = pwtData.get(year);
  if (entry && entry.rnna !== undefined) setValue(pwtSheet, `B${r}`, entry.rnna);
  if (entry && entry.rkna !== undefined) setValue(pwtSheet, `C${r}`, entry.rkna);
}

// Update WEO_Data sheet
const weoSheet = wb.Sheets['WEO_Data'];
for (let r = 8; r <= 51; r++) {
  const year = weoSheet[`B${r}`]?.v;
  if (!year) continue;
  if (year >= 2000 && year <= 2027) {
    const entry = weoData.get(year);
    if (entry) {
      if (entry.gdp !== null) setValue(weoSheet, `C${r}`, entry.gdp);
      if (entry.gr !== null) setValue(weoSheet, `D${r}`, entry.gr);
    }
  } else if (year >= 2028 && year <= 2043) {
    // Keep 2027 growth rate constant
    setFormula(weoSheet, `D${r}`, `=$D$35`);
    // Project GDP level using growth rate
    setFormula(weoSheet, `C${r}`, `=C${r - 1}*(1+D${r}/100)`);
  }
}

// Update CFC data sheet
const cfcSheet = wb.Sheets['CFC data'];
for (let r = 2; r <= 29; r++) {
  const year = cfcSheet[`B${r}`]?.v;
  if (!year) continue;
  const val = cfcData.get(year);
  if (val !== undefined) setValue(cfcSheet, `C${r}`, val);
  // Capital stock link to PWT
  setFormula(cfcSheet, `D${r}`, `=XLOOKUP(B${r},PWT!$A$2:$A$35,PWT!$C$2:$C$35,"")`);
  // Depreciation rate
  setFormula(cfcSheet, `E${r}`, `=IFERROR(C${r}/D${r},"")`);
}

// Update Production sheet
const prodSheet = wb.Sheets['Production'];
// Annual depreciation rate (avg of last 8 non-blank years)
setFormula(prodSheet, 'B3', `=AVERAGE(OFFSET('CFC data'!$E$2,COUNT('CFC data'!$E$2:$E$29)-8,0,8,1))`);

// Link K and Y for HP filter section (2002-2023)
for (let r = 6; r <= 27; r++) {
  setFormula(prodSheet, `D${r}`, `=XLOOKUP(C${r},PWT!$A$2:$A$35,PWT!$C$2:$C$35,"")`);
  setFormula(prodSheet, `E${r}`, `=XLOOKUP(C${r},WEO_Data!$B$8:$B$51,WEO_Data!$C$8:$C$51,"")`);
  setFormula(prodSheet, `F${r}`, `=LN(D${r})`);
  setFormula(prodSheet, `G${r}`, `=LN(E${r})`);
  setFormula(prodSheet, `K${r}`, `=G${r}-$B$2*F${r}`);
  setFormula(prodSheet, `L${r}`, `=K${r}`);
  setFormula(prodSheet, `N${r}`, `=K${r}-L${r}`);
}
// Second-order difference (start at row 8)
for (let r = 6; r <= 27; r++) {
  if (r < 8) {
    delete prodSheet[`M${r}`];
  } else {
    setFormula(prodSheet, `M${r}`, `=L${r}-2*L${r-1}+L${r-2}`);
  }
}
// Objective in P5
setFormula(prodSheet, 'P5', `=SUMSQ(N6:N27)+100*SUMSQ(M8:M27)`);

// K/Y anchor label and value (avg of 2011-2019)
prodSheet['C33'] = { t: 's', v: 'K/Y anchor (avg 2011-2019)' };
setFormula(prodSheet, 'D33', `=AVERAGE(D45:D53)`);

// Second table (2002-2041)
for (let r = 36; r <= 75; r++) {
  // Y from WEO
  setFormula(prodSheet, `F${r}`, `=XLOOKUP(C${r},WEO_Data!$B$8:$B$51,WEO_Data!$C$8:$C$51,"")`);
  // K/Y ratio
  setFormula(prodSheet, `D${r}`, `=IF(C${r}<=2019,E${r}/F${r},$D$33)`);
  // K level
  setFormula(prodSheet, `E${r}`, `=IF(C${r}<=2019,XLOOKUP(C${r},PWT!$A$2:$A$35,PWT!$C$2:$C$35,""),D${r}*F${r})`);
  // LnZ trend (link or extend)
  if (r <= 57) {
    const srcRow = r - 30; // 36->6
    setFormula(prodSheet, `G${r}`, `=L${srcRow}`);
  } else {
    setFormula(prodSheet, `G${r}`, `=TREND($G$36:$G$57,$C$36:$C$57,C${r})`);
  }
  // Ystar_base
  setFormula(prodSheet, `H${r}`, `=EXP(G${r})*(E${r}^$B$2)`);
  // Investment
  setFormula(prodSheet, `I${r}`, `=IFERROR(XLOOKUP(C${r},Investment!$B$2:$B$9,Investment!$C$2:$C$9,0),0)`);
  // Delta K
  setFormula(prodSheet, `J${r}`, `=IF(C${r}<2026,0,(1-$B$3)*J${r-1}+I${r})`);
  // K with investment
  setFormula(prodSheet, `K${r}`, `=E${r}+J${r}`);
  // Ystar_with
  setFormula(prodSheet, `L${r}`, `=EXP(G${r})*(K${r}^$B$2)`);
  // Uplift
  setFormula(prodSheet, `M${r}`, `=IF(H${r}=0,"",L${r}/H${r}-1)`);
  // Projected GDP
  setFormula(prodSheet, `N${r}`, `=F${r}*(1+M${r})`);
  // Projected GDP Growth
  setFormula(prodSheet, `O${r}`, `=IF(C${r}=2002,"",N${r}/N${r-1}-1)`);
  // Baseline GDP Growth
  setFormula(prodSheet, `P${r}`, `=IF(C${r}=2002,"",F${r}/F${r-1}-1)`);
}

x.writeFile(wb, 'test-supply.xlsx');
